"""Общий набор A/A-тестов для уроков 11.4 «Ловушки» и 11.5 «CUPED и последовательные тесты».

Модель A/A-теста: 28 дней, в каждую группу каждый день приходят 1 000 новых людей, каждый покупает
с вероятностью 14% (масштаб checkout_v2); у теста 10 независимых метрик такого же устройства.
После каждого дня считают z-тест для двух долей по накопленным данным. Зерно 1104: повторный запуск
даёт те же 20 000 прогонов.

Сто тестов, которые показывают интерактивы обеих страниц, — прогоны 17300–17399. Это блок из ста прогонов
подряд, выбранный из двухсот так, чтобы его доли ложноположительных результатов были ближе всего к долям по всем 20 000;
тест сцены страницы 11.4 — прогон 17359 из этого блока. Выбор делает sim.py страницы 11.4.

Запуск из корня папки материалов: python data/ab/aa_sim.py
"""
import numpy as np
from scipy import stats

SEED, RUNS, DAYS, N, P, M = 1104, 20_000, 28, 1_000, 0.14, 10
Z = stats.norm.isf(0.025)                                       # 1,959964: |z| ≥ Z ⇔ p < 0,05
BLOCK, SCENE = 173, 17359                                       # блок ста показанных тестов и тест сцены 11.4


def counts():
    """Покупки за день в группах A и B: два массива (RUNS, M, DAYS) — прогон, метрика, день."""
    rng = np.random.default_rng(SEED)
    return rng.binomial(N, P, (RUNS, M, DAYS)), rng.binomial(N, P, (RUNS, M, DAYS))


def zpath(ca, cb):
    """z-статистика по накопленным покупкам: ca, cb — (…, DAYS) покупок за день."""
    n = N * np.arange(1, DAYS + 1)
    a, b = ca.cumsum(-1), cb.cumsum(-1)
    pool = (a + b) / (2 * n)
    return (b - a) / n / np.sqrt(pool * (1 - pool) * 2 / n)


def looks(k):
    """Дни промежуточных проверок и финального анализа при k проверках: ceil(28·j/k), k = 4 → 7, 14, 21, 28."""
    return [-(-DAYS * j // k) for j in range(1, k + 1)]


def shown():
    """Номера ста показанных прогонов: тест сцены первым."""
    return [SCENE] + [i for i in range(BLOCK * 100, BLOCK * 100 + 100) if i != SCENE]


def false_wins(sig, k, m=1):
    """Доля тестов с ложной победой: хотя бы одна из первых m метрик хотя бы в один из k взглядов дала p < 0,05."""
    return sig[:, :m][:, :, [d - 1 for d in looks(k)]].any(-1).any(-1).mean()


if __name__ == "__main__":
    sig = np.abs(zpath(*counts())) >= Z
    print(f"{RUNS} A/A-тестов, {DAYS} дней, по {N} человек в группу в день, конверсия {P:.0%}")
    print("проверок  одна метрика  десять метрик  в ста показанных (одна метрика)")
    for k in (1, 2, 4, 14, 28):
        print(f"{k:>8}  {false_wins(sig, k):>11.1%}  {false_wins(sig, k, M):>12.1%}  {int(false_wins(sig[shown()], k) * 100 + .5):>8}")

# Вывод:
# 20000 A/A-тестов, 28 дней, по 1000 человек в группу в день, конверсия 14%
# проверок  одна метрика  десять метрик  в ста показанных (одна метрика)
#        1         5.1%         39.7%         4
#        2         8.8%         58.0%         6
#        4        13.0%         74.5%        10
#       14        22.6%         91.7%        24
#       28        28.0%         96.0%        30
